/** Mức xử lý chứng từ — parity PKH / voucher-setup (1 · 5 · 9). */

export const PROCESSING_LEVEL_OPTIONS = [
  { value: '1', label: 'Mức 1: Nhập liệu' },
  { value: '5', label: 'Mức 5: Kiểm tra' },
  { value: '9', label: 'Mức 9: Hoạch toán' },
] as const;

/** Map Status BE (Draft|Posted) → mức xử lý hiển thị khi chưa persist ProcessingLevel. */
export function statusToProcessingLevel(status?: string | null): string {
  const s = (status || '').trim().toLowerCase();
  if (s === 'posted') return '9';
  return '1';
}

export function processingLevelLabel(level: string): string {
  const hit = PROCESSING_LEVEL_OPTIONS.find(o => o.value === level);
  return hit?.label ?? `Mức ${level}`;
}

/** Tag color hint for list column. */
export function processingLevelTagColor(level: string): 'blue' | 'gold' | 'green' | 'default' {
  if (level === '9') return 'green';
  if (level === '5') return 'gold';
  if (level === '1') return 'blue';
  return 'default';
}
